"""HTML presentation generated by Python; no frontend framework or build step.

HTML/CSS are the browser's display formats. The only JavaScript below opens
Plaid's external login window; it does not classify or analyze transactions.
"""

from html import escape
from urllib.parse import urlencode


def text(value):
    return escape(str(value), quote=True)


def money(amount, currency, decimals=0):
    prefix = {"USD": "$", "CAD": "CA$", "EUR": "€", "GBP": "£"}.get(
        currency, currency + " "
    )
    return f"{prefix}{amount:,.{decimals}f}"


def chart(months, currency):
    """Draw a small accessible SVG bar chart directly from monthly totals."""
    maximum = max(1, *(max(month["income"], month["expenses"]) for month in months))
    ceiling = max(1000, int(maximum / 1000 + 1) * 1000)
    parts = [
        '<svg viewBox="0 0 900 270" role="img" aria-label="Monthly income and expenses"><title>Monthly income and expenses</title>'
    ]
    for step in range(5):
        value = ceiling * step / 4
        y = 220 - step * 48
        parts.append(
            f'<line x1="55" x2="890" y1="{y}" y2="{y}" stroke="#e5e7eb"/><text x="45" y="{y + 4}" text-anchor="end" fill="#718096" font-size="11">{value / 1000:g}k</text>'
        )
    for index, month in enumerate(months):
        x = 88 + index * 118
        for offset, key, color in [
            (0, "income", "#315d9c"),
            (30, "expenses", "#b8c0cc"),
        ]:
            height = max(0, month[key]) / ceiling * 192
            parts.append(
                f'<rect x="{x + offset}" y="{220 - height}" width="25" height="{height}" fill="{color}"><title>{text(month["month"])} {key}: {text(money(month[key], currency))}</title></rect>'
            )
        parts.append(
            f'<text x="{x + 28}" y="245" text-anchor="middle" fill="#687483" font-size="12">{text(month["label"])}</text>'
        )
    parts.append(
        '</svg><p class="legend"><span style="color:#315d9c">■ Income</span> &nbsp; <span style="color:#788390">■ Expenses</span></p>'
    )
    return "".join(parts)


def overview(report, currency):
    current = report["current"]
    metrics = [
        ("Income this month", money(current["income"], currency), "Month to date"),
        (
            "Monthly average",
            money(report["average"], currency),
            f"{report['complete_months']} completed months with records",
        ),
        (
            "Net cash flow",
            money(current["income"] - current["expenses"], currency),
            "Income − expenses this month",
        ),
        (
            "Income stability",
            "—" if report["score"] is None else f"{report['score']}/100",
            "Needs 3 completed months"
            if report["score"] is None
            else "Based on monthly income variation",
        ),
    ]
    totals = "".join(
        f"<div><dt>{text(label)}</dt><dd>{text(value)}</dd><small>{text(note)}</small></div>"
        for label, value, note in metrics
    )
    sources = "".join(
        f'<tr><td>{text(source["source"])}</td><td>{source["count"]}</td><td>{"Recurring · " + str(source["months"]) + " months" if source["recurring"] else "Occasional"}</td><td class="number">{text(money(source["total"], currency))}</td></tr>'
        for source in report["sources"]
    )
    if not sources:
        sources = '<tr><td colspan="4">No income found in this currency.</td></tr>'
    return f"""<dl class="totals">{totals}</dl>
    <section class="chart-section"><h3>Monthly income and expenses</h3><p class="muted">Six previous months and the current partial month.</p>{chart(report["months"], currency)}</section>
    <section><h3>Income sources</h3><p class="muted">Grouped by cleaned description over the displayed period.</p><div class="table-scroll"><table><thead><tr><th>Source</th><th>Payments</th><th>Pattern</th><th class="number">Total</th></tr></thead><tbody>{sources}</tbody></table></div></section>"""


